public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    ParameterizedType paramType = (ParameterizedType) genericType;
    Type[] typeArguments = paramType.getActualTypeArguments();
    TypeVariable<?>[] typeParameters = targetType.getTypeParameters();

    if (typeArguments.length != typeParameters.length) {
        return null;
    }

    Map<TypeVariable<?>, Class<?>> typeMap = new HashMap<>();
    for (int i = 0; i < typeParameters.length; i++) {
        typeMap.put(typeParameters[i], (Class<?>) typeArguments[i]);
    }

    Class<?>[] resolvedArguments = new Class<?>[typeArguments.length];
    for (int i = 0; i < typeArguments.length; i++) {
        if (typeArguments[i] instanceof TypeVariable) {
            resolvedArguments[i] = typeMap.get(typeArguments[i]);
        } else if (typeArguments[i] instanceof Class) {
            resolvedArguments[i] = (Class<?>) typeArguments[i];
        } else {
            return null;
        }
    }

    return resolvedArguments;
}

