private static String substituteVariables(String value, Properties props) {
    StringBuilder sb = new StringBuilder();
    int i = 0;
    while (i < value.length()) {
        int j = value.indexOf("${", i);
        if (j == -1) {
            sb.append(value.substring(i));
            i = value.length();
        } else {
            sb.append(value.substring(i, j));
            int k = value.indexOf("}", j + 2);
            if (k == -1) {
                sb.append(value.substring(j));
                i = value.length();
            } else {
                String varName = value.substring(j + 2, k);
                String varValue = props.getProperty(varName);
                if (varValue != null) {
                    sb.append(varValue);
                } else {
                    sb.append(value.substring(j, k + 1));
                }
                i = k + 1;
            }
        }
    }
    return sb.toString();
}

