import java.io.IOException;

public class StringUtils {
    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }
        StringBuilder writer = new StringBuilder(str.length());
        int sz = str.length();
        StringBuilder unicode = new StringBuilder(4);
        boolean hadSlash = false;
        boolean inUnicode = false;
        for (int i = 0; i < sz; i++) {
            char ch = str.charAt(i);
            if (inUnicode) {
                unicode.append(ch);
                if (unicode.length() == 4) {
                    try {
                        int value = Integer.parseInt(unicode.toString(), 16);
                        writer.append((char) value);
                        unicode.setLength(0);
                        inUnicode = false;
                        hadSlash = false;
                    } catch (NumberFormatException nfe) {
                        throw new IOException("Invalid unicode escape sequence: \u" + unicode + " at " + (i - 5));
                    }
                }
                continue;
            }
            if (!hadSlash) {
                if (ch == '\\') {
                    hadSlash = true;
                } else {
                    writer.append(ch);
                }
                continue;
            }
            hadSlash = false;
            switch (ch) {
            case '\\':
                writer.append('\\');
                break;
            case '\'':
                writer.append('\'');
                break;
            case '\"':
                writer.append('"');
                break;
            case 'r':
                writer.append('\r');
                break;
            case 'f':
                writer.append('\f');
                break;
            case 't':
                writer.append('\t');
                break;
            case 'n':
                writer.append('\n');
                break;
            case 'b':
                writer.append('\b');
                break;
            case 'u':
                inUnicode = true;
                break;
            default:
                throw new IOException("Invalid escape sequence: \\" + ch + " at " + (i - 1));
            }
        }
        if (hadSlash) {
            writer.append('\\');
        }
        return writer.toString();
    }
}

