protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }

    // Assuming the graph is connected and the tour is a valid Hamiltonian cycle
    V startVertex = graph.getEdgeTarget(tour.iterator().next());
    GraphPath<V, E> path = new DijkstraShortestPath<>(graph).getPath(startVertex, startVertex);

    for (E edge : tour) {
        if (!path.getEdgeList().contains(edge)) {
            path.getEdgeList().add(edge);
            V target = graph.getEdgeTarget(edge);
            path.getVertexList().add(target);
        }
    }

    return path;
}

