    int currentChar;
    while ((currentChar = reader.read()) != -1) {
        char ch = (char) currentChar;
        boolean isTerminator = false;
        for (char terminator : terminators) {
            if (ch == terminator) {
                isTerminator = true;
                break;
            }
        }
        if (isTerminator) {
            break;
        }
        token.append(ch);
    }
    return token.toString();
}

